text:
procedure Write_Unit_Information (Unit_Num : Unit_Number_Type) is
   Unode : constant Node_Id   := Cunit (Unit_Num);
   Ukind : constant Node_Kind := Nkind (Unit (Unode));
   Uent  : constant Entity_Id := Cunit_Entity (Unit_Num);
   Pnode : Node_Id;

begin
   Write_Info_Initiate ('U');
   Write_Info_Char (' ');
   Write_Info_Name (Unit_Name (Unit_Num));
   Write_Info_Tab (25);
   Write_Info_Name (Unit_File_Name (Unit_Num));

   Write_Info_Tab (49);
   Write_Info_Str (Version_Get (Unit_Num));

   --  Add BD parameter if Elaborate_Body pragma desirable

   if Ekind (Uent) = E_Package
     and then Elaborate_Body_Desirable (Uent)
   then
      Write_Info_Str (" BD");
   end if;

   --  Add BN parameter if body needed for SAL

   if (Is_Subprogram (Uent)
        or else Ekind (Uent) = E_Package
        or else Is_Generic_Unit (Uent))
     and then Body_Needed_For_SAL (Uent)
   then
      Write_Info_Str (" BN");
   end if;

   if Dynamic_Elab (Unit_Num) then
      Write_Info_Str (" DE");
   end if;

   --  Set the Elaborate_Body indication if either an explicit pragma
   --  was present, or if this is an instantiation.

   if Has_Pragma_Elaborate_Body (Uent)
     or else (Ukind = N_Package_Declaration
               and then Is_Generic_Instance (Uent)
               and then Present (Corresponding_Body (Unit (Unode))))
   then
      Write_Info_Str (" EB");
   end if;

   --  Now see if we should tell the binder that an elaboration entity
   --  is present, which must be set to true during elaboration.
   --  We generate the indication if the following condition is met:

   --  If this is a spec ...

   if (Is_Subprogram (Uent)
        or else Ekind (Uent) = E_Package
        or else Is_Generic_Unit (Uent))

      --  and an elaboration entity was declared ...

      and then Present (Elaboration_Entity (Uent))

      --  and either the elaboration flag is required ...

      and then (Elaboration_Entity_Required (Uent)

         --  or this unit has elaboration code ...

         or else not Has_No_Elaboration_Code (Unode)

         --  or this unit has a separate body and this
         --  body has elaboration code.

         or else
           (Ekind (Uent) = E_Package
             and then Present (Body_Entity (Uent))
             and then
               not Has_No_Elaboration_Code
                     (Parent (Declaration_Node (Body_Entity (Uent))))))
   then
      Write_Info_Str (" EE");
   end if;

   if Has_No_Elaboration_Code (Unode) then
      Write_Info_Str (" NE");
   end if;

   Write_Info_Str (" O");
   Write_Info_Char (OA_Setting (Unit_Num));

   --  For a package instance with a body that is a library unit, the two
   --  compilation units share Cunit_Entity so we cannot rely on Uent.

   if Ukind in N_Package_Declaration | N_Package_Body then
      declare
         E : constant Entity_Id := Defining_Entity (Unit (Unode));

      begin
         if Ekind (E) in E_Package | E_Package_Body
           and then Present (Finalizer (E))
         then
            Write_Info_Str (" PF");
         end if;
      end;
   end if;

   if Is_Preelaborated (Uent) then
      Write_Info_Str (" PR");
   end if;

   if Is_Pure (Uent) then
      Write_Info_Str (" PU");
   end if;

   if Has_RACW (Unit_Num) then
      Write_Info_Str (" RA");
   end if;

   if Is_Remote_Call_Interface (Uent) then
      Write_Info_Str (" RC");
   end if;

   if Is_Remote_Types (Uent) then
      Write_Info_Str (" RT");
   end if;

   if Serious_Errors_Detected /= 0 then
      Write_Info_Str (" SE");
   end if;

   if Is_Shared_Passive (Uent) then
      Write_Info_Str (" SP");
   end if;

   if Ukind = N_Subprogram_Declaration
     or else Ukind = N_Subprogram_Body
   then
      Write_Info_Str (" SU");

   elsif Ukind = N_Package_Declaration
           or else
         Ukind = N_Package_Body
   then
      --  If this is a wrapper package for a subprogram instantiation,
      --  the user view is the subprogram. Note that in this case the
      --  ali file contains both the spec and body of the instance.

      if Is_Wrapper_Package (Uent) then
         Write_Info_Str (" SU");
      else
         Write_Info_Str (" PK");
      end if;

   elsif Ukind = N_Generic_Package_Declaration then
      Write_Info_Str (" PK");

   end if;

   if Ukind in N_Generic_Declaration
     or else
       (Ukind in N_Lib_Unit_Body
          and then Present (Spec_Lib_Unit (Unode))
          and then Nkind (Unit (Spec_Lib_Unit (Unode)))
            in N_Generic_Declaration)
   then
      Write_Info_Str (" GE");
   end if;

   if not Is_Internal_Unit (Unit_Num) then
      case Identifier_Casing (Source_Index (Unit_Num)) is
         when All_Lower_Case => Write_Info_Str (" IL");
         when All_Upper_Case => Write_Info_Str (" IU");
         when others         => null;
      end case;

      case Keyword_Casing (Source_Index (Unit_Num)) is
         when Mixed_Case     => Write_Info_Str (" KM");
         when All_Upper_Case => Write_Info_Str (" KU");
         when others         => null;
      end case;
   end if;

   if Initialize_Scalars or else Invalid_Value_Used then
      Write_Info_Str (" IS");
   end if;

   Write_Info_EOL;

   --  Generate with lines, first those that are directly with'ed

   for J in With_Flags'Range loop
      With_Flags         (J) := False;
      Elab_Flags         (J) := False;
      Elab_All_Flags     (J) := False;
      Elab_Des_Flags     (J) := False;
      Elab_All_Des_Flags (J) := False;
      Has_Implicit_With  (J) := Unknown;
   end loop;

   Collect_Withs (Unode);

   --  For a body, we must also check for any subunits which belong to
   --  it and which have context clauses of their own, since these
   --  with'ed units are part of its own elaboration dependencies.

   if Nkind (Unit (Unode)) in N_Lib_Unit_Body then
      for S in Units.First .. Last_Unit loop

         --  We are only interested in subunits. For preproc. data and
         --  def. files, Cunit is Empty, so we need to test that first.

         if Cunit (S) /= Empty
           and then Nkind (Unit (Cunit (S))) = N_Subunit

--  Generate task stack lines

if Primary_Stack_Count (Unit_Num) > 0
  or else Sec_Stack_Count (Unit_Num) > 0
then
   Write_Info_Initiate ('T');
   Write_Info_Char (' ');
   Write_Info_Int (Primary_Stack_Count (Unit_Num));
   Write_Info_Char (' ');
   Write_Info_Int (Sec_Stack_Count (Unit_Num));
   Write_Info_EOL;
end if;

   procedure M_Parameters is
   begin
      if Main_Priority (Main_Unit) /= Default_Main_Priority then
         Write_Info_Char (' ');
         Write_Info_Nat (Main_Priority (Main_Unit));
      end if;

      if Opt.Time_Slice_Set then
         Write_Info_Str (" T=");
         Write_Info_Nat (Opt.Time_Slice_Value);
      end if;

      if Main_CPU (Main_Unit) /= Default_Main_CPU then
         Write_Info_Str (" C=");
         Write_Info_Nat (Main_CPU (Main_Unit));
      end if;

      Write_Info_Str (" W=");
      Write_Info_Char
        (WC_Encoding_Letters (Wide_Character_Encoding_Method));

      Write_Info_EOL;
   end M_Parameters;

--  Start of processing for Output_Main_Program_Line

begin
   if Nkind (U) = N_Subprogram_Body
     or else
       (Nkind (U) = N_Package_Body
         and then
           Nkind (Original_Node (U)) in N_Subprogram_Instantiation)
   then
      --  If the unit is a subprogram instance, the entity for the
      --  subprogram is the alias of the visible entity, which is the
      --  related instance of the wrapper package. We retrieve the
      --  subprogram declaration of the desired entity.

      if Nkind (U) = N_Package_Body then
         U := Parent (Parent (
             Alias (Related_Instance (Defining_Unit_Name
               (Specification (Unit (Spec_Lib_Unit (Parent (U)))))))));
      end if;

      S := Specification (U);

      --  A generic subprogram is never a main program

      if Nkind (U) = N_Subprogram_Body
        and then Present (Corresponding_Spec (U))
        and then Is_Generic_Subprogram (Corresponding_Spec (U))
      then
         null;

      elsif No (Parameter_Specifications (S)) then
         if Nkind (S) = N_Procedure_Specification then
            Write_Info_Initiate ('M');
            Write_Info_Str (" P");
            M_Parameters;

         else
            declare
               Nam : Node_Id := Defining_Unit_Name (S);

            begin
               --  If it is a child unit, get its simple name

               if Nkind (Nam) = N_Defining_Program_Unit_Name then
                  Nam := Defining_Identifier (Nam);
               end if;

               if Is_Integer_Type (Etype (Nam)) then
                  Write_Info_Initiate ('M');
                  Write_Info_Str (" F");
                  M_Parameters;
               end if;
            end;
         end if;
      end if;
   end if;

--  Output parameters ('P') line

Write_Info_Initiate ('P');

if Compilation_Errors then
   Write_Info_Str (" CE");
end if;

if Opt.Detect_Blocking then
   Write_Info_Str (" DB");
end if;

if Locking_Policy /= ' ' then
   Write_Info_Str  (" L");
   Write_Info_Char (Locking_Policy);
end if;

if Queuing_Policy /= ' ' then
   Write_Info_Str  (" Q");
   Write_Info_Char (Queuing_Policy);
end if;

if Task_Dispatching_Policy /= ' ' then
   Write_Info_Str  (" T");
   Write_Info_Char (Task_Dispatching_Policy);
end if;

if GNATprove_Mode then
   Write_Info_Str (" GP");
end if;

if Partition_Elaboration_Policy /= ' ' then
   Write_Info_Str  (" E");
   Write_Info_Char (Partition_Elaboration_Policy);
end if;

if Opt.Interrupts_System_By_Default then
   Write_Info_Str (" ID");
end if;

if No_Component_Reordering_Config then
   Write_Info_Str (" NC");
end if;

if not Object then
   Write_Info_Str (" NO");
end if;

if No_Run_Time_Mode then
   Write_Info_Str (" NR");
end if;

if Normalize_Scalars then
   Write_Info_Str (" NS");
end if;

if Default_SSO_Config /= ' ' then
   Write_Info_Str (" O");
   Write_Info_Char (Default_SSO_Config);
end if;

if Sec_Stack_Used then
   Write_Info_Str (" SS");
end if;

if Unreserve_All_Interrupts then
   Write_Info_Str (" UA");
end if;

if ZCX_Exceptions then
   Write_Info_Str (" ZX");
end if;

Write_Info_EOL;

--  Before outputting the restrictions line, update the setting of
--  the No_Elaboration_Code flag. Violations of this restriction
--  cannot be detected until after the backend has been called since
--  it is the backend that sets this flag. We have to check all units
--  for which we have generated code

for Unit in Units.First .. Last_Unit loop
   if Units.Table (Unit).Generate_Code then
      if not Has_No_Elaboration_Code (Cunit (Unit)) then
         Main_Restrictions.Violated (No_Elaboration_Code) := True;
         exit;
      end if;
   end if;
end loop;

--  Positional case (only if debug flag -gnatd.R is set)

if Debug_Flag_Dot_RR then

   --  Output first restrictions line

   Write_Info_Initiate ('R');
   Write_Info_Char (' ');

   --  First the information for the boolean restrictions

   for R in All_Boolean_Restrictions loop
      if Main_Restrictions.Set (R)
        and then not Restriction_Warnings (R)
      then
         Write_Info_Char ('r');
      elsif Main_Restrictions.Violated (R) then
         Write_Info_Char ('v');
      else
         Write_Info_Char ('n');
      end if;
   end loop;

   --  And now the information for the parameter restrictions

   for RP in All_Parameter_Restrictions loop
      if Main_Restrictions.Set (RP)
        and then not Restriction_Warnings (RP)
      then
         Write_Info_Char ('r');
         Write_Info_Nat (Nat (Main_Restrictions.Value (RP)));
      else
         Write_Info_Char ('n');
      end if;

      if not Main_Restrictions.Violated (RP)
        or else RP not in Checked_Parameter_Restrictions
      then
         Write_Info_Char ('n');
      else
         Write_Info_Char ('v');
         Write_Info_Nat (Nat (Main_Restrictions.Count (RP)));

         if Main_Restrictions.Unknown (RP) then
            Write_Info_Char ('+');
         end if;
      end if;
   end loop;

   Write_Info_EOL;

--  Named case (if debug flag -gnatd.R is not set)

else
   declare
      C : Character;

   begin
      --  Write RN header line with preceding blank line

      Write_Info_EOL;
      Write_Info_Initiate ('R');
      Write_Info_Char ('N');
      Write_Info_EOL;

      --  First the lines for the boolean restrictions

      for R in All_Boolean_Restrictions loop
         if Main_Restrictions.Set (R)
           and then not Restriction_Warnings (R)
         then
            C := 'R';
         elsif Main_Restrictions.Violated (R) then
            C := 'V';
         else
            goto Continue;
         end if;

         Write_Info_Initiate ('R');
         Write_Info_Char (C);
         Write_Info_Char (' ');
         Write_Info_Str (All_Boolean_Restrictions'Image (R));
         Write_Info_EOL;

      <<Continue>>
         null;
      end loop;
   end;

   --  And now the lines for the parameter restrictions

   for RP in All_Parameter_Restrictions loop
      if Main_Restrictions.Set (RP)
        and then not Restriction_Warnings (RP)
      then
         Write_Info_Initiate ('R');
         Write_Info_Str ("R ");
         Write_Info_Str (All_Parameter_Restrictions'Image (RP));
         Write_Info_Char ('=');
         Write_Info_Nat (Nat (Main_Restrictions.Value (RP)));
         Write_Info_EOL;
      end if;

      if not Main_Restrictions.Violated (RP)
        or else RP not in Checked_Parameter_Restrictions
      then
         null;
      else
         Write_Info_Initiate ('R');
         Write_Info_Str ("V ");
         Write_Info_Str (All_Parameter_Restrictions'Image (RP));
         Write_Info_Char ('=');
         Write_Info_Nat (Nat (Main_Restrictions.Count (RP)));

         if Main_Restrictions.Unknown (RP) then
            Write_Info_Char ('+');
         end if;

         Write_Info_EOL;
      end if;
   end loop;
end if;

--  Output R lines for No_Dependence entries

ALIs.Table (Id) := (
  Afile                        => F,
  Compile_Errors               => False,
  First_CUDA_Kernel            => CUDA_Kernels.Last + 1,
  First_Interrupt_State        => Interrupt_States.Last + 1,
  First_Sdep                   => No_Sdep_Id,
  First_Specific_Dispatching   => Specific_Dispatching.Last + 1,
  First_Unit                   => No_Unit_Id,
  GNATprove_Mode               => False,
  Interrupts_Default_To_System => False,
  Invocation_Graph_Encoding    => No_Encoding,
  Last_CUDA_Kernel             => CUDA_Kernels.Last,
  Last_Interrupt_State         => Interrupt_States.Last,
  Last_Sdep                    => No_Sdep_Id,
  Last_Specific_Dispatching    => Specific_Dispatching.Last,
  Last_Unit                    => No_Unit_Id,
  Locking_Policy               => ' ',
  Main_Priority                => -1,
  Main_CPU                     => -1,
  Main_Program                 => None,
  No_Component_Reordering      => False,
  No_Object                    => False,
  Normalize_Scalars            => False,
  Ofile_Full_Name              => Full_Object_File_Name,
  Partition_Elaboration_Policy => ' ',
  Queuing_Policy               => ' ',
  Restrictions                 => No_Restrictions,
  SAL_Interface                => False,
  Sfile                        => No_File,
  SSO_Default                  => ' ',
  Task_Dispatching_Policy      => ' ',
  Time_Slice_Value             => -1,
  WC_Encoding                  => 'b',
  Unit_Exception_Table         => False,
  Ver                          => (others => ' '),
  Ver_Len                      => 0,
  Zero_Cost_Exceptions         => False);

--  Now we acquire the input lines from the ALI file. Note that the
--  convention in the following code is that as we enter each section,
--  C is set to contain the first character of the following line.

C := Getc;
Check_Unknown_Line;

--  Acquire library version

if C /= 'V' then

   --  The V line missing really indicates trouble, most likely it
   --  means we don't have an ALI file at all, so here we give a
   --  fatal error even if we are in Ignore_Errors mode.

   Fatal_Error;

elsif Ignore ('V') then
   Skip_Line;

else
   Checkc (' ');
   Skip_Space;
   Checkc ('"');

   for J in 1 .. Ver_Len_Max loop
      C := Getc;
      exit when C = '"';
      ALIs.Table (Id).Ver (J) := C;
      ALIs.Table (Id).Ver_Len := J;
   end loop;

   Skip_Eol;
end if;

C := Getc;
Check_Unknown_Line;

--  Acquire main program line if present

if C = 'M' then
   if Ignore ('M') then
      Skip_Line;

   else
      Checkc (' ');
      Skip_Space;

      C := Getc;

      if C = 'F' then
         ALIs.Table (Id).Main_Program := Func;
      elsif C = 'P' then
         ALIs.Table (Id).Main_Program := Proc;
      else
         P := P - 1;
         Fatal_Error;
      end if;

      Skip_Space;

      if not At_Eol then
         if Nextc < 'A' then
            ALIs.Table (Id).Main_Priority := Get_Nat;
         end if;

         Skip_Space;

         if Nextc = 'T' then
            P := P + 1;
            Checkc ('=');
            ALIs.Table (Id).Time_Slice_Value := Get_Nat;
         end if;

         Skip_Space;

         if Nextc = 'C' then
            P := P + 1;
            Checkc ('=');
            ALIs.Table (Id).Main_CPU := Get_Nat;
         end if;

         Skip_Space;

         Checkc ('W');
         Checkc ('=');
         ALIs.Table (Id).WC_Encoding := Getc;
      end if;

      Skip_Eol;
   end if;

   C := Getc;
end if;

--  Acquire argument lines

First_Arg := Args.Last + 1;

A_Loop : loop
   Check_Unknown_Line;
   exit A_Loop when C /= 'A';

   if Ignore ('A') then
      Skip_Line;

   else
      Checkc (' ');

      --  Scan out argument

      Name_Len := 0;
      while not At_Eol loop
         Add_Char_To_Name_Buffer (Getc);
      end loop;

Check_Unknown_Line;

while C /= 'P' loop
   if Ignore_Errors then
      if C = EOF then
         Fatal_Error;
      else
         Skip_Line;
         C := Nextc;
      end if;
   else
      Fatal_Error;
   end if;
end loop;

if Ignore ('P') then
   Skip_Line;

--  Process P line

else
   NS_Found := False;

   while not At_Eol loop
      Checkc (' ');
      Skip_Space;
      C := Getc;

      --  Processing for CE

      if C = 'C' then
         Checkc ('E');
         ALIs.Table (Id).Compile_Errors := True;

      --  Processing for DB

      elsif C = 'D' then
         Checkc ('B');
         Detect_Blocking := True;

      --  Processing for Ex

      elsif C = 'E' then
         Partition_Elaboration_Policy_Specified := Getc;
         ALIs.Table (Id).Partition_Elaboration_Policy :=
           Partition_Elaboration_Policy_Specified;

      --  Processing for FX

      elsif C = 'F' then
         C := Getc;

         --  Old front-end exceptions marker, ignore

         if C = 'X' then
            null;
         else
            Fatal_Error_Ignore;
         end if;

      --  Processing for GP

      elsif C = 'G' then
         Checkc ('P');
         GNATprove_Mode_Specified := True;
         ALIs.Table (Id).GNATprove_Mode := True;

      --  Processing for ID (Interrupts Default to System)

      elsif C = 'I' then
         Checkc ('D');
         Interrupts_Default_To_System_Specified := True;
         ALIs.Table (Id).Interrupts_Default_To_System := True;

      --  Processing for Lx

      elsif C = 'L' then
         Locking_Policy_Specified := Getc;
         ALIs.Table (Id).Locking_Policy := Locking_Policy_Specified;

      --  Processing for flags starting with N

      elsif C = 'N' then
         C := Getc;

         --  Processing for NC

         if C = 'C' then
            ALIs.Table (Id).No_Component_Reordering := True;
            No_Component_Reordering_Specified := True;

         --  Processing for NO

         elsif C = 'O' then
            ALIs.Table (Id).No_Object := True;
            No_Object_Specified := True;

         --  Processing for NR

         elsif C = 'R' then
            No_Run_Time_Mode           := True;
            Configurable_Run_Time_Mode := True;

         --  Processing for NS

         elsif C = 'S' then
            ALIs.Table (Id).Normalize_Scalars := True;
            Normalize_Scalars_Specified := True;
            NS_Found := True;

         --  Invalid switch starting with N

         else
            Fatal_Error_Ignore;
         end if;

      --  Processing for OH/OL

      elsif C = 'O' then
         C := Getc;

         if C = 'L' or else C = 'H' then
            ALIs.Table (Id).SSO_Default := C;
            SSO_Default_Specified := True;

         else
            Fatal_Error_Ignore;
         end if;

      --  Processing for Qx

      elsif C = 'Q' then
         Queuing_Policy_Specified := Getc;
         ALIs.Table (Id).Queuing_Policy := Queuing_Policy_Specified;

      --  Processing for flags starting with S

      elsif C = 'S' then
         C := Getc;

         --  Processing for SL

         if C = 'L' then
            ALIs.Table (Id).SAL_Interface := True;

         --  Processing for SS

         elsif C = 'S' then
            --  Special case: a-tags/i-c* by themselves should not set
            --  Sec_Stack_Used, only if other code uses the secondary
            --  stack should we set this flag. This ensures that we do
            --  not bring the secondary stack unnecessarily when using
            --  one of these packages and not actually using the
            --  secondary stack.

            declare
               File : constant String := Get_Name_String (F);
            begin
               if File /= "a-tags.ali"
                 and then File /= "i-c.ali"
                 and then File /= "i-cstrin.ali"
                 and then File /= "i-cpoint.ali"
               then
                  Opt.Sec_Stack_Used := True;
               end if;
            end;

         --  Invalid switch starting with S

         else
            Fatal_Error_Ignore;
         end if;

      --  Processing for Tx

      elsif C = 'T' then
         Task_Dispatching_Policy_Specified := Getc;
         ALIs.Table (Id).Task_Dispatching_Policy :=
           Task_Dispatching_Policy_Specified;

      --  Processing for switch starting with U

      elsif C = 'U' then
         C := Getc;

         --  Processing for UA

         if C  = 'A' then
            Unreserve_All_Interrupts_Specified := True;

         --  Processing for UX

         elsif C = 'X' then
            ALIs.Table (Id).Unit_Exception_Table := True;

         --  Invalid switches starting with U

         else
            Fatal_Error_Ignore;
         end if;

      --  Processing for ZX

      elsif C = 'Z' then
         C := Getc;

         if C = 'X' then
            ALIs.Table (Id).Zero_Cost_Exceptions := True;
            Zero_Cost_Exceptions_Specified := True;
         else
            Fatal_Error_Ignore;
         end if;

      --  Invalid parameter

      else
         C := Getc;
         Fatal_Error_Ignore;
      end if;
   end loop;

   if not NS_Found then
      No_Normalize_Scalars_Specified := True;
   end if;

      C := Getc;
   end loop;

--  Here we process the restrictions lines (other than unit name cases)

else
   Scan_Restrictions : declare
      Save_R : constant Restrictions_Info := Cumulative_Restrictions;
      --  Save cumulative restrictions in case we have a fatal error

      Bad_R_Line : exception;
      --  Signal bad restrictions line (raised on unexpected character)

      Typ : Character;
      R   : Restriction_Id;
      N   : Natural;

   begin
      --  Named restriction case

      if Nextc = 'N' then
         Skip_Line;
         C := Getc;

         --  Loop through RR and RV lines

         while C = 'R' and then Nextc /= ' ' loop
            Typ := Getc;
            Checkc (' ');

            --  Acquire restriction name

            Name_Len := 0;
            while not At_Eol and then Nextc /= '=' loop
               Name_Len := Name_Len + 1;
               Name_Buffer (Name_Len) := Getc;
            end loop;

            --  Now search list of restrictions to find match

            declare
               RN : String renames Name_Buffer (1 .. Name_Len);

            begin
               R := Restriction_Id'First;
               while R /= Not_A_Restriction_Id loop
                  if Restriction_Id'Image (R) = RN then
                     goto R_Found;
                  end if;

                  R := Restriction_Id'Succ (R);
               end loop;

               --  We don't recognize the restriction. This might be
               --  thought of as an error, and it really is, but we
               --  want to allow building with inconsistent versions
               --  of the binder and ali files (see comments at the
               --  start of package System.Rident), so we just ignore
               --  this situation.

               goto Done_With_Restriction_Line;
            end;

            <<R_Found>>

            case R is

               --  Boolean restriction case

               when All_Boolean_Restrictions =>
                  case Typ is
                     when 'V' =>
                        ALIs.Table (Id).Restrictions.Violated (R) :=
                          True;
                        Cumulative_Restrictions.Violated (R) := True;

                     when 'R' =>
                        ALIs.Table (Id).Restrictions.Set (R) := True;
                        Cumulative_Restrictions.Set (R) := True;

                     when others =>
                        raise Bad_R_Line;
                  end case;

               --  Parameter restriction case

               when All_Parameter_Restrictions =>
                  if At_Eol or else Nextc /= '=' then
                     raise Bad_R_Line;
                  else
                     Skipc;
                  end if;

                  N := Natural (Get_Nat);

                  case Typ is

                     --  Restriction set

                     when 'R' =>
                        ALIs.Table (Id).Restrictions.Set (R) := True;
                        ALIs.Table (Id).Restrictions.Value (R) := N;

                        if Cumulative_Restrictions.Set (R) then
                           Cumulative_Restrictions.Value (R) :=
                             Integer'Min
                               (Cumulative_Restrictions.Value (R), N);
                        else
                           Cumulative_Restrictions.Set (R) := True;
                           Cumulative_Restrictions.Value (R) := N;
                        end if;

                     --  Restriction violated

                     when 'V' =>
                        ALIs.Table (Id).Restrictions.Violated (R) :=
                          True;
                        Cumulative_Restrictions.Violated (R) := True;
                        ALIs.Table (Id).Restrictions.Count (R) := N;

                        --  Checked Max_Parameter case

                        if R in Checked_Max_Parameter_Restrictions then
                           Cumulative_Restrictions.Count (R) :=
                             Integer'Max
                               (Cumulative_Restrictions.Count (R), N);

                        --  Other checked parameter cases

                        else
                           declare
                              pragma Unsuppress (Overflow_Check);

                           begin
                              Cumulative_Restrictions.Count (R) :=
                                Cumulative_Restrictions.Count (R) + N;

                           exception
                              when Constraint_Error =>

                                 --  A constraint error comes from the
                                 --  addition. We reset to the maximum
                                 --  and indicate that the real value
                                 --  is now unknown.

                                 Cumulative_Restrictions.Value (R) :=
                                   Integer'Last;
                                 Cumulative_Restrictions.Unknown (R) :=
                                   True;
                           end;
                        end if;

                        --  Deal with + case

                        if Nextc = '+' then
                           Skipc;
                           ALIs.Table (Id).Restrictions.Unknown (R) :=
                             True;
                           Cumulative_Restrictions.Unknown (R) := True;
                        end if;

                     --  Other than 'R' or 'V'

   ALIs.Table (Id).First_Unit := Units.Last;
end if;

declare
   UL : Unit_Record renames Units.Table (Units.Last);

begin
   UL.Uname                      := Get_Unit_Name;
   UL.Predefined                 := Is_Predefined_Unit;
   UL.Internal                   := Is_Internal_Unit;
   UL.My_ALI                     := Id;
   UL.Sfile                      := Get_File_Name (Lower => True);
   UL.Pure                       := False;
   UL.Preelab                    := False;
   UL.No_Elab                    := False;
   UL.Shared_Passive             := False;
   UL.RCI                        := False;
   UL.Remote_Types               := False;
   UL.Serious_Errors             := False;
   UL.Has_RACW                   := False;
   UL.Init_Scalars               := False;
   UL.Is_Generic                 := False;
   UL.Icasing                    := Mixed_Case;
   UL.Kcasing                    := All_Lower_Case;
   UL.Dynamic_Elab               := False;
   UL.Elaborate_Body             := False;
   UL.Set_Elab_Entity            := False;
   UL.Version                    := "00000000";
   UL.First_With                 := Withs.Last + 1;
   UL.First_Arg                  := First_Arg;
   UL.First_Invocation_Construct := Invocation_Constructs.Last + 1;
   UL.Last_Invocation_Construct  := No_Invocation_Construct;
   UL.First_Invocation_Relation  := Invocation_Relations.Last + 1;
   UL.Last_Invocation_Relation   := No_Invocation_Relation;
   UL.Elab_Position              := 0;
   UL.SAL_Interface              := ALIs.Table (Id).SAL_Interface;
   UL.Directly_Scanned           := Directly_Scanned;
   UL.Body_Needed_For_SAL        := False;
   UL.Elaborate_Body_Desirable   := False;
   UL.Optimize_Alignment         := 'O';
   UL.Has_Finalizer              := False;
   UL.Primary_Stack_Count        := 0;
   UL.Sec_Stack_Count            := 0;

   if C in '0' .. '9' or else C in 'a' .. 'f' then
      Units.Table (Units.Last).Version (1) := C;

      for J in 2 .. 8 loop
         C := Getc;
         Units.Table (Units.Last).Version (J) := C;
      end loop;

   --  BD/BN parameters

   elsif C = 'B' then
      C := Getc;

      if C = 'D' then
         Check_At_End_Of_Field;
         Units.Table (Units.Last).Elaborate_Body_Desirable := True;

      elsif C = 'N' then
         Check_At_End_Of_Field;
         Units.Table (Units.Last).Body_Needed_For_SAL := True;

      else
         Fatal_Error_Ignore;
      end if;

   --  DE parameter (Dynamic elaboration checks)

   elsif C = 'D' then
      C := Getc;

      if C = 'E' then
         Check_At_End_Of_Field;
         Units.Table (Units.Last).Dynamic_Elab := True;
         Dynamic_Elaboration_Checks_Specified := True;
      else
         Fatal_Error_Ignore;
      end if;

   --  EB/EE parameters

   elsif C = 'E' then
      C := Getc;

      if C = 'B' then
         Units.Table (Units.Last).Elaborate_Body := True;
      elsif C = 'E' then
         Units.Table (Units.Last).Set_Elab_Entity := True;
      else
         Fatal_Error_Ignore;
      end if;

      Check_At_End_Of_Field;

   --  GE parameter (generic)

   elsif C = 'G' then
      C := Getc;

      if C = 'E' then
         Check_At_End_Of_Field;
         Units.Table (Units.Last).Is_Generic := True;
      else
         Fatal_Error_Ignore;
      end if;

   --  IL/IS/IU parameters

   elsif C = 'I' then
      C := Getc;

      if C = 'L' then
         Units.Table (Units.Last).Icasing := All_Lower_Case;
      elsif C = 'S' then
         Units.Table (Units.Last).Init_Scalars := True;
         Initialize_Scalars_Used := True;
      elsif C = 'U' then
         Units.Table (Units.Last).Icasing := All_Upper_Case;
      else
         Fatal_Error_Ignore;
      end if;

      Check_At_End_Of_Field;

   --  KM/KU parameters

   elsif C = 'K' then
      C := Getc;

      if C = 'M' then
         Units.Table (Units.Last).Kcasing := Mixed_Case;
      elsif C = 'U' then
         Units.Table (Units.Last).Kcasing := All_Upper_Case;
      else
         Fatal_Error_Ignore;
      end if;

      Check_At_End_Of_Field;

   --  NE parameter

   elsif C = 'N' then
      C := Getc;

      if C = 'E' then
         Units.Table (Units.Last).No_Elab := True;
         Check_At_End_Of_Field;
      else
         Fatal_Error_Ignore;
      end if;

   --  PF/PR/PU/PK parameters

   elsif C = 'P' then
      C := Getc;

      if C = 'F' then
         Units.Table (Units.Last).Has_Finalizer := True;
      elsif C = 'R' then
         Units.Table (Units.Last).Preelab := True;
      elsif C = 'U' then
         Units.Table (Units.Last).Pure := True;
      elsif C = 'K' then
         Units.Table (Units.Last).Unit_Kind := 'p';
      else
         Fatal_Error_Ignore;
      end if;

      Check_At_End_Of_Field;

   --  OL/OO/OS/OT parameters

   elsif C = 'O' then
      C := Getc;

      if C = 'L' or else C = 'O' or else C = 'S' or else C = 'T' then
         Units.Table (Units.Last).Optimize_Alignment := C;
      else
         Fatal_Error_Ignore;
      end if;

      Check_At_End_Of_Field;

   --  RC/RT parameters

   elsif C = 'R' then
      C := Getc;

      if C = 'C' then
         Units.Table (Units.Last).RCI := True;
      elsif C = 'T' then
         Units.Table (Units.Last).Remote_Types := True;
      elsif C = 'A' then
         Units.Table (Units.Last).Has_RACW := True;
      else
         Fatal_Error_Ignore;
      end if;

      Check_At_End_Of_Field;

   --  SE/SP/SU parameters

   elsif C = 'S' then
      C := Getc;

      if C = 'E' then
         Units.Table (Units.Last).Serious_Errors := True;
      elsif C = 'P' then
         Units.Table (Units.Last).Shared_Passive := True;
      elsif C = 'U' then
         Units.Table (Units.Last).Unit_Kind := 's';
      else
         Fatal_Error_Ignore;
      end if;

      Check_At_End_Of_Field;

   else
      C := Getc;
      Fatal_Error_Ignore;
   end if;
end loop;

Skip_Eol;

C := Getc;

--  Scan out With lines for this unit

With_Loop : loop
   Check_Unknown_Line;
   exit With_Loop when C /= 'W' and then C /= 'Y' and then C /= 'Z';

   if Ignore ('W') then
      Skip_Line;

   else
      Checkc (' ');
      Skip_Space;
      Withs.Increment_Last;
      Withs.Table (Withs.Last) :=
        (Uname              => Get_Unit_Name,
         Sfile              => No_File,
         Afile              => No_File,
         Elaborate          => False,
         Elaborate_All      => False,
         Elab_Desirable     => False,
         Elab_All_Desirable => False,
         SAL_Interface      => False,
         Limited_With       => (C = 'Y'),
         Implicit_With      => (C = 'Z'));

else
   Checkc (' ');
   Skip_Space;

   Units.Table (Units.Last).Primary_Stack_Count := Get_Nat;
   Skip_Space;
   Units.Table (Units.Last).Sec_Stack_Count := Get_Nat;
   Skip_Space;
   Skip_Eol;

ALIs.Table (Id).Last_Unit := Units.Last;
ALIs.Table (Id).Sfile := Units.Table (ALIs.Table (Id).First_Unit).Sfile;

--  Set types of the units (there can be at most 2 of them)

if ALIs.Table (Id).First_Unit /= ALIs.Table (Id).Last_Unit then
   Units.Table (ALIs.Table (Id).First_Unit).Utype := Is_Body;
   Units.Table (ALIs.Table (Id).Last_Unit).Utype  := Is_Spec;

else
   --  Deal with body only and spec only cases, note that the reason we
   --  do our own checking of the name (rather than using Is_Body_Name)
   --  is that Uname drags in far too much compiler junk.

   Get_Name_String (Units.Table (Units.Last).Uname);

   if Name_Buffer (Name_Len) = 'b' then
      Units.Table (Units.Last).Utype := Is_Body_Only;
   else
      Units.Table (Units.Last).Utype := Is_Spec_Only;
   end if;
end if;

procedure Gen_Adainit (Elab_Order : Unit_Id_Array) is
   Main_Priority : Int renames ALIs.Table (ALIs.First).Main_Priority;
   Main_CPU      : Int renames ALIs.Table (ALIs.First).Main_CPU;

if Cumulative_Restrictions.Set
     (No_Standard_Allocators_After_Elaboration)
then
   WBI ("      System.Elaboration_Allocators."
        & "Mark_Start_Of_Elaboration;");
end if;

--  Generate assignments to initialize globals

Set_String ("      Main_Priority := ");
Set_Int    (Main_Priority);
Set_Char   (';');
Write_Statement_Buffer;

Set_String ("      Time_Slice_Value := ");

if Task_Dispatching_Policy_Specified = 'F'
  and then ALIs.Table (ALIs.First).Time_Slice_Value = -1
then
   Set_Int (0);
else
   Set_Int (ALIs.Table (ALIs.First).Time_Slice_Value);
end if;

Set_Char   (';');
Write_Statement_Buffer;

Set_String ("      WC_Encoding := '");
Set_Char   (Get_WC_Encoding);

Set_String ("';");
Write_Statement_Buffer;

Set_String ("      Locking_Policy := '");
Set_Char   (Locking_Policy_Specified);
Set_String ("';");
Write_Statement_Buffer;

Set_String ("      Queuing_Policy := '");
Set_Char   (Queuing_Policy_Specified);
Set_String ("';");
Write_Statement_Buffer;

Set_String ("      Task_Dispatching_Policy := '");
Set_Char   (Task_Dispatching_Policy_Specified);
Set_String ("';");
Write_Statement_Buffer;

if System_Tasking_Restricted_Stages_Used
  and then Partition_Elaboration_Policy_Specified = 'S'
then
   Set_String ("      Partition_Elaboration_Policy := '");
   Set_Char   (Partition_Elaboration_Policy_Specified);
   Set_String ("';");
   Write_Statement_Buffer;
end if;

Gen_Restrictions;

WBI ("      Priority_Specific_Dispatching :=");
WBI ("        Local_Priority_Specific_Dispatching'Address;");

Set_String ("      Num_Specific_Dispatching := ");
Set_Int (PSD_Pragma_Settings.Last + 1);
Set_Char (';');
Write_Statement_Buffer;

Set_String ("      Main_CPU := ");
Set_Int    (Main_CPU);
Set_Char   (';');
Write_Statement_Buffer;

WBI ("      Interrupt_States := Local_Interrupt_States'Address;");

Set_String ("      Num_Interrupt_States := ");
Set_Int (IS_Pragma_Settings.Last + 1);
Set_Char (';');
Write_Statement_Buffer;

Set_String ("      Unreserve_All_Interrupts := ");

if Unreserve_All_Interrupts_Specified then
   Set_String ("1");
else
   Set_String ("0");
end if;

Set_Char (';');
Write_Statement_Buffer;

if Exception_Tracebacks or Exception_Tracebacks_Symbolic then
   WBI ("      Exception_Tracebacks := 1;");

   if Exception_Tracebacks_Symbolic then
      WBI ("      Exception_Tracebacks_Symbolic := 1;");
   end if;
end if;

Set_String ("      Detect_Blocking := ");

if Detect_Blocking then
   Set_Int (1);
else
   Set_Int (0);
end if;

Set_String (";");
Write_Statement_Buffer;

Set_String ("      Default_Stack_Size := ");
Set_Int (Default_Stack_Size);
Set_String (";");
Write_Statement_Buffer;

if Interrupts_Default_To_System_Specified then
   Set_String ("      Interrupts_Default_To_System := 1;");
   Write_Statement_Buffer;
end if;

if Leap_Seconds_Support then
   WBI ("      Leap_Seconds_Support := 1;");
end if;

if XDR_Stream then
   WBI ("      XDR_Stream := 1;");
end if;

if Bind_Env_String_Built then
   WBI ("      Bind_Env_Addr := Bind_Env'Address;");
end if;

      --  sized secondary stack pool.

      WBI ("      " & Get_Ada_Main_Name & "'Elab_Body;");

      --  Generate the default-sized secondary stack pool and set the
      --  related secondary stack globals.

      Set_String ("      Default_Secondary_Stack_Size := ");

      if Opt.Default_Sec_Stack_Size /= Opt.No_Stack_Size then
         Set_Int (Opt.Default_Sec_Stack_Size);
      else
         Set_String ("System.Parameters.Runtime_Default_Sec_Stack_Size");
      end if;

      Set_Char (';');
      Write_Statement_Buffer;

      Set_String ("      Binder_Sec_Stacks_Count := ");
      Set_Int (Num_Sec_Stacks);
      Set_Char (';');
      Write_Statement_Buffer;

      Set_String ("      Default_Sized_SS_Pool := ");

      if Num_Sec_Stacks > 0 then
         Set_String ("Sec_Default_Sized_Stacks'Address;");
      else
         Set_String ("System.Null_Address;");
      end if;

      Write_Statement_Buffer;
      WBI ("");
   end if;

   --  Generate call to Runtime_Initialize

   WBI ("      Runtime_Initialize (1);");

   --  Generate call to Tasking_Runtime_Initialize

   if With_GNARL then
      WBI ("      Tasking_Runtime_Initialize;");
   end if;
end if;

--  Generate call to set Initialize_Scalar values if active

if Initialize_Scalars_Used then
   WBI ("");
   Set_String ("      System.Scalar_Values.Initialize ('");
   Set_Char (Initialize_Scalars_Mode1);
   Set_String ("', '");
   Set_Char (Initialize_Scalars_Mode2);
   Set_String ("');");
   Write_Statement_Buffer;
end if;

procedure Gen_Elab_Calls (Elab_Order : Unit_Id_Array) is
   Check_Elab_Flag : Boolean;

begin
   --  Loop through elaboration order entries

   for E in Elab_Order'Range loop
      declare
         Unum : constant Unit_Id := Elab_Order (E);
         U    : Unit_Record renames Units.Table (Unum);

         Unum_Spec : Unit_Id;
         --  This is the unit number of the spec that corresponds to
         --  this entry. It is the same as Unum except when the body
         --  and spec are different and we are currently processing
         --  the body, in which case it is the spec (Unum + 1).

      begin
         if U.Utype = Is_Body then
            Unum_Spec := Unum + 1;
         else
            Unum_Spec := Unum;
         end if;

         --  Nothing to do if predefined unit in no run time mode

         if No_Run_Time_Mode and then U.Predefined then
            null;

         --  Likewise if this is an interface to a stand alone library

         elsif U.SAL_Interface then
            null;

         --  Case of no elaboration code

         elsif U.No_Elab

           --  In CodePeer mode, we special case subprogram bodies which
           --  are handled in the 'else' part below, and lead to a call
           --  to <subp>'Elab_Subp_Body.

           and then (not CodePeer_Mode

                      --  Test for spec

                      or else U.Utype = Is_Spec
                      or else U.Utype = Is_Spec_Only
                      or else U.Unit_Kind /= 's')
         then
            --  In the case of a body with a separate spec, where the
            --  separate spec has an elaboration entity defined, this is
            --  where we increment the elaboration entity if one exists.

            --  Likewise for lone specs with an elaboration entity defined
            --  despite No_Elaboration_Code, e.g. when requested to preserve
            --  control flow.

            if (U.Utype = Is_Body or else U.Utype = Is_Spec_Only)
              and then Units.Table (Unum_Spec).Set_Elab_Entity
              and then not CodePeer_Mode
            then
               Set_String ("      E");
               Set_Unit_Number (Unum_Spec);
               Set_String (" := E");
               Set_Unit_Number (Unum_Spec);
               Set_String (" + 1;");
               Write_Statement_Buffer;
            end if;

         --  Here if elaboration code is present. If binding a library
         --  or if there is a non-Ada main subprogram then we generate:

         --    if uname_E = 0 then
         --       uname'elab_[spec|body];
         --    end if;
         --    uname_E := uname_E + 1;

         --  Otherwise, elaboration routines are called unconditionally:

         --    uname'elab_[spec|body];
         --    uname_E := uname_E + 1;

         --  The uname_E increment is skipped if this is a separate spec,
         --  since it will be done when we process the body.

         --  In CodePeer mode, we do not generate any reference to xxx_E
         --  variables, only calls to 'Elab* subprograms.

         else
            --  Check incompatibilities with No_Multiple_Elaboration

            if not CodePeer_Mode
              and then Cumulative_Restrictions.Set (No_Multiple_Elaboration)
            then
               --  Force_Checking_Of_Elaboration_Flags (-F) not allowed

               if Force_Checking_Of_Elaboration_Flags then
                  Osint.Fail
                    ("-F (force elaboration checks) switch not allowed "
                     & "with restriction No_Multiple_Elaboration active");

               --  Interfacing of libraries not allowed

               elsif Interface_Library_Unit then
                  Osint.Fail
                    ("binding of interfaced libraries not allowed "
                     & "with restriction No_Multiple_Elaboration active");

               --  Non-Ada main program not allowed

               elsif not Bind_Main_Program then
                  Osint.Fail
                    ("non-Ada main program not allowed "
                     & "with restriction No_Multiple_Elaboration active");
               end if;
            end if;

            --  OK, see if we need to test elaboration flag

            Check_Elab_Flag :=
              Units.Table (Unum_Spec).Set_Elab_Entity
                and then Check_Elaboration_Flags
                and then not CodePeer_Mode
                and then (Force_Checking_Of_Elaboration_Flags
                           or Interface_Library_Unit
                           or not Bind_Main_Program);

            if Check_Elab_Flag then
               Set_String ("      if E");
               Set_Unit_Number (Unum_Spec);
               Set_String (" = 0 then");
               Write_Statement_Buffer;
               Set_String ("   ");
            end if;

            Set_String ("      ");
            Get_Decoded_Name_String_With_Brackets (U.Uname);

            if Name_Buffer (Name_Len) = 's' then
               Name_Buffer (Name_Len - 1 .. Name_Len + 8) :=
                 "'elab_spec";
               Name_Len := Name_Len + 8;

            --  Special case in CodePeer mode for subprogram bodies
            --  which correspond to CodePeer 'Elab_Subp_Body special
            --  init procedure.

            elsif U.Unit_Kind = 's' and CodePeer_Mode then
               Name_Buffer (Name_Len - 1 .. Name_Len + 13) :=
                 "'elab_subp_body";
               Name_Len := Name_Len + 13;

            else
               Name_Buffer (Name_Len - 1 .. Name_Len + 8) :=
                 "'elab_body";
               Name_Len := Name_Len + 8;
            end if;

            Set_Casing (U.Icasing);
            Set_Name_Buffer;
            Set_Char (';');
            Write_Statement_Buffer;

            if Check_Elab_Flag then
               WBI ("      end if;");
            end if;

            if U.Utype /= Is_Spec
              and then not CodePeer_Mode
              and then Units.Table (Unum_Spec).Set_Elab_Entity
            then
               Set_String ("      E");
               Set_Unit_Number (Unum_Spec);
               Set_String (" := E");
               Set_Unit_Number (Unum_Spec);
               Set_String (" + 1;");
               Write_Statement_Buffer;
            end if;
         end if;

procedure Gen_Elab_Externals (Elab_Order : Unit_Id_Array) is
begin
   if CodePeer_Mode then
      return;
   end if;

   for E in Elab_Order'Range loop
      declare
         Unum : constant Unit_Id := Elab_Order (E);
         U    : Unit_Record renames Units.Table (Unum);

      begin
         --  Check for Elab_Entity to be set for this unit

         if U.Set_Elab_Entity

           --  Don't generate reference for stand alone library

           and then not U.SAL_Interface

           --  Don't generate reference for predefined file in No_Run_Time
           --  mode, since we don't include the object files in this case

           and then not (No_Run_Time_Mode and then U.Predefined)
         then
            Get_Name_String (U.Sfile);
            Set_String ("   ");
            Set_String ("E");
            Set_Unit_Number (Unum);
            Set_String (" : Short_Integer; pragma Import (Ada, E");
            Set_Unit_Number (Unum);
            Set_String (", """);
            Get_Name_String (U.Uname);
            Set_Unit_Name;
            Set_String ("_E"");");
            Write_Statement_Buffer;
         end if;
      end;
   end loop;

U    := Units.Table (Unum);

--  Dealing with package bodies is a little complicated. In such
--  cases we must retrieve the package spec since it contains the
--  spec of the body finalizer.

if U.Utype = Is_Body then
   Unum  := Unum + 1;
   Uspec := Units.Table (Unum);
else
   Uspec := U;
end if;

Get_Name_String (Uspec.Uname);

--  We are only interested in non-generic packages

if U.Unit_Kind /= 'p' or else U.Is_Generic then
   null;

--  That aren't an interface to a stand alone library

elsif U.SAL_Interface then
   null;

--  Case of no finalization

elsif not U.Has_Finalizer then

   --  The only case in which we have to do something is if this
   --  is a body, with a separate spec, where the separate spec
   --  has a finalizer. In that case, this is where we decrement
   --  the elaboration entity.

   if U.Utype = Is_Body and then Uspec.Has_Finalizer then
      if not Lib_Final_Built then
         Gen_Header;
         Lib_Final_Built := True;
      end if;

if Time_Slice_Set then
   ALIs.Table (ALIs.First).Time_Slice_Value := Opt.Time_Slice_Value;
end if;

--  Count the number of statically allocated stacks to be generated by
--  the binder. If the user has specified the number of default-sized
--  secondary stacks, use that number. Otherwise start the count at one
--  as the binder is responsible for creating a secondary stack for the
--  main task.

if Opt.Quantity_Of_Default_Size_Sec_Stacks /= -1 then
   Num_Sec_Stacks := Quantity_Of_Default_Size_Sec_Stacks;
elsif Sec_Stack_Used then
   Num_Sec_Stacks := 1;
end if;

for J in Units.First .. Units.Last loop
   Num_Sec_Stacks :=
     Num_Sec_Stacks + Units.Table (J).Sec_Stack_Count;
end loop;

--  Generate output file in appropriate language

