function Has_Finalizer (Elab_Order : Unit_Id_Array) return Boolean is
   U     : Unit_Record;
   Unum  : Unit_Id;

begin
   for E in reverse Elab_Order'Range loop
      Unum := Elab_Order (E);
      U    := Units.Table (Unum);

      --  We are only interested in non-generic packages

      if U.Unit_Kind = 'p'
        and then U.Has_Finalizer
        and then not U.Is_Generic
        and then not U.No_Elab
      then
         return True;
      end if;
   end loop;

   return False;

end if;

Start_String;
Wide_Character_Found      := False;
Wide_Wide_Character_Found := False;
Scan_Ptr := Scan_Ptr + 1;

--  Loop to scan out characters of string literal

loop
   C := Source (Scan_Ptr);

   if C = Delimiter then
      Accumulate_Checksum (C);
      Scan_Ptr := Scan_Ptr + 1;
      exit when Source (Scan_Ptr) /= Delimiter;

      --  Unlike normal string literals, doubled delimiter has no
      --  special significance in interpolated string literals.

      if Inside_Interpolated_String_Literal then
         Error_Msg_S
           ("double quotations not allowed in interpolated string");
      end if;

      Code := Get_Char_Code (C);
      Accumulate_Checksum (C);
      Scan_Ptr := Scan_Ptr + 1;

         end case;

      elsif Start_Of_Wide_Character then
         Wptr := Scan_Ptr;
         Scan_Wide (Source, Scan_Ptr, Code, Err);

         if Err then
            Error_Illegal_Wide_Character;
            Code := Get_Char_Code (' ');
         else
            Check_Bidi (Code);
         end if;

         Accumulate_Checksum (Code);

         --  In Ada 95 mode we allow any wide characters in a string
         --  but in Ada 2005, the set of characters allowed has been
         --  restricted to graphic characters.

         if Ada_Version >= Ada_2005
           and then Is_UTF_32_Non_Graphic (UTF_32 (Code))
         then
            Error_Msg
              ("(Ada 2005) non-graphic character not permitted " &
               "in string literal", Wptr);
         end if;

      else
         Accumulate_Checksum (C);

         if C not in Graphic_Character then
            if C in Line_Terminator then
               Error_Unterminated_String;
               exit;

            elsif C in Upper_Half_Character then
               if Ada_Version = Ada_83 then
                  Error_Bad_String_Char;
               end if;

            else
               Error_Bad_String_Char;
            end if;
         end if;

         Code := Get_Char_Code (C);
         Scan_Ptr := Scan_Ptr + 1;
      end if;
   end if;

   Store_String_Char (Code);

   if not In_Character_Range (Code) then
      if In_Wide_Character_Range (Code) then
         Wide_Character_Found := True;
      else
         Wide_Wide_Character_Found := True;
      end if;
   end if;
end loop;

function Start_Of_Wide_Character return Boolean is
   C : constant Character := Source (Scan_Ptr);

begin
   --  ESC encoding method with ESC present

   if C = ESC
     and then Wide_Character_Encoding_Method in WC_ESC_Encoding_Method
   then
      return True;

   --  Upper half character with upper half encoding

   elsif C in Upper_Half_Character and then Upper_Half_Encoding then
      return True;

   --  Brackets encoding

   elsif C = '['
     and then Source (Scan_Ptr + 1) = '"'
     and then Identifier_Char (Source (Scan_Ptr + 2))
   then
      return True;

   --  Not the start of a wide character

   else
      return False;
   end if;
end Start_Of_Wide_Character;

procedure Check_Restriction
  (Msg_Issued : out Boolean;
   R          : Restriction_Id;
   N          : Node_Id;
   V          : Uint := Uint_Minus_1)
is
   VV : Integer;
   --  V converted to integer form. If V is greater than Integer'Last,
   --  it is reset to minus 1 (unknown value).

   procedure Update_Restrictions (Info : in out Restrictions_Info);
   --  Update violation information in Info.Violated and Info.Count

   -------------------------
   -- Update_Restrictions --
   -------------------------

   procedure Update_Restrictions (Info : in out Restrictions_Info) is
   begin
      --  If not violated, set as violated now

      if not Info.Violated (R) then
         Info.Violated (R) := True;

         if R in All_Parameter_Restrictions then
            if VV < 0 then
               Info.Unknown (R) := True;
               Info.Count (R) := 1;

            else
               Info.Count (R) := VV;
            end if;
         end if;

      --  Otherwise if violated already and a parameter restriction,
      --  update count by maximizing or summing depending on restriction.

      elsif R in All_Parameter_Restrictions then

         --  If new value is unknown, result is unknown

         if VV < 0 then
            Info.Unknown (R) := True;

         --  If checked by maximization, nothing to do because the
         --  check is per-object.

         elsif R in Checked_Max_Parameter_Restrictions then
            null;

         --  If checked by adding, do add, checking for overflow

         elsif R in Checked_Add_Parameter_Restrictions then
            declare
               pragma Unsuppress (Overflow_Check);
            begin
               Info.Count (R) := Info.Count (R) + VV;
            exception
               when Constraint_Error =>
                  Info.Count (R) := Integer'Last;
                  Info.Unknown (R) := True;
            end;

         --  Should not be able to come here, known counts should only
         --  occur for restrictions that are Checked_max or Checked_Sum.

         else
            raise Program_Error;
         end if;
      end if;
   end Update_Restrictions;

--  Start of processing for Check_Restriction

begin
   Msg_Issued := False;

   --  In CodePeer mode, we do not want to check for any restriction, or set
   --  additional restrictions other than those already set in gnat1drv.adb
   --  so that we have consistency between each compilation.

   --  In GNATprove mode restrictions are checked, except for
   --  No_Initialize_Scalars, which is implicitly set in gnat1drv.adb.

   if CodePeer_Mode
     or else (GNATprove_Mode and then R = No_Initialize_Scalars)
   then
      return;
   end if;

   if UI_Is_In_Int_Range (V) then
      VV := Integer (UI_To_Int (V));
   else
      VV := -1;
   end if;

   --  Count can only be specified in the checked val parameter case

   pragma Assert (VV < 0 or else R in Checked_Val_Parameter_Restrictions);

   --  Nothing to do if value of zero specified for parameter restriction

   if VV = 0 then
      return;
   end if;

   --  Update current restrictions

   Update_Restrictions (Restrictions);

   --  If in main extended unit, update main restrictions as well. Note
   --  that as usual we check for Main_Unit explicitly to deal with the
   --  case of configuration pragma files.

   if Current_Sem_Unit = Main_Unit
     or else In_Extended_Main_Source_Unit (N)
   then
      Update_Restrictions (Main_Restrictions);
   end if;

   declare
      use Local_Restrictions;
   begin
      if Local_Restriction_Checking_Hook /= null then
         --  A given global restriction (which may or may not be in
         --  effect) has been violated. Even if the global restriction
         --  is not in effect, a corresponding local restriction may be
         --  in effect (in which case the violation needs to be flagged).
         Local_Restriction_Checking_Hook.all (R, N);
      end if;
   end;

   --  Nothing to do if restriction message suppressed

   if Suppress_Restriction_Message (N) then
      null;

   --  If restriction not set, nothing to do

   elsif not Restrictions.Set (R) then
      null;

   --  Don't complain about No_Obsolescent_Features in an instance, since we
   --  will complain on the template, which is much better. Are there other
   --  cases like this ??? Do we need a more general mechanism ???

   elsif R = No_Obsolescent_Features
     and then Instantiation_Location (Sloc (N)) /= No_Location
   then
      null;

   --  Here if restriction set, check for violation (this is a Boolean
   --  restriction, or a parameter restriction with a value of zero and an
   --  unknown count, or a parameter restriction with a known value that
   --  exceeds the restriction count).

   elsif R in All_Boolean_Restrictions
     or else (Restrictions.Unknown (R)
                and then Restrictions.Value (R) = 0)
     or else Restrictions.Count (R) > Restrictions.Value (R)
   then
      Msg_Issued := True;
      Restriction_Msg (R, N);
   end if;

   --  For Max_Entries and the like, do not carry forward the violation
   --  count because it does not affect later declarations.

   if R in Checked_Max_Parameter_Restrictions then
      Restrictions.Count (R) := 0;
      Restrictions.Violated (R) := False;

